import json
import sys


def extract_fields(data):
    """Extract exact, case-sensitive labels from colon-delimited lines."""
    invalid = {"error": "invalid_input"}
    if not isinstance(data, dict) or set(data) != {"text", "fields"}:
        return invalid
    text, labels = data["text"], data["fields"]
    if not isinstance(text, str) or len(text) > 100000:
        return invalid
    if not isinstance(labels, list) or not 1 <= len(labels) <= 100:
        return invalid
    if any(not isinstance(label, str) for label in labels):
        return invalid
    if len(set(labels)) != len(labels):
        return invalid

    requested = set(labels)
    found = {}
    for line in text.splitlines():
        label, separator, value = line.partition(":")
        if not separator or label not in requested:
            continue
        if label in found:
            return invalid
        found[label] = value.strip()
    return {"fields": {label: found[label] for label in labels if label in found}}


def main():
    try:
        data = json.load(sys.stdin)
        result = extract_fields(data)
    except (ValueError, UnicodeError, RecursionError):
        result = {"error": "invalid_input"}
    json.dump(result, sys.stdout, ensure_ascii=True)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
